function companyPage(){const roles=[["Девелопмент","Формирует продукт и модель развития.",FACTORY_MEDIA.commercial],["Организация проекта","Собирает участников и структуру проекта.",FACTORY_MEDIA.teamAlt],["Управление проектом","Управляет сроками, бюджетом и изменениями.",FACTORY_MEDIA.financeAlt2],["Операционное управление","Подключается к запуску и эксплуатации, если это предусмотрено моделью.",FACTORY_MEDIA.hospitalityAlt]];return '<div class="wrap page"><div class="eyebrow">Компания</div><h1>MMW-COMPANY</h1><p class="lead">Девелоперская и проектная система, которая собирает идею, актив, экономику, организацию и управление в единый контур.</p><div class="media-grid">'+mediaCard(FACTORY_MEDIA.governance,"РАЗВИТИЕ MMW","Создание управляемого проекта","Продукт, площадка, капитал, команда, реализация и результат рассматриваются как единая система.",true)+mediaCard(FACTORY_MEDIA.financeAlt,"КОМАНДА","Команда и партнёры","Компетенции подключаются по роли и стадии: девелопмент, управление проектами, архитектура, инженерия, финансы, коммерция и операционная деятельность.")+'</div><section><h2>Роль MMW</h2><div class="grid">'+roles.map((x,i)=>visualCard(x[2],"0"+(i+1),x[0],x[1])).join('')+'</div></section><section><h2>Направления</h2><div class="media-grid">'+mediaCard(FACTORY_MEDIA.residential,"НЕДВИЖИМОСТЬ","Недвижимость","Жилые и коммерческие проекты, где земля, продукт, экономика и реализация рассматриваются вместе.")+mediaCard(FACTORY_MEDIA.logisticsAlt,"ИНФРАСТРУКТУРА","Инфраструктура","Логистика, агро, энергетика и другие инфраструктурные модели с отдельной экономикой.")+mediaCard(FACTORY_MEDIA.hospitality,"ГОСТЕПРИИМСТВО","Hospitality","Туристические и hospitality-проекты с продуктом, загрузкой, сервисами и операционной моделью.")+'</div></section><section><h2>ЭКОНОМИКА MMW-COMPANY</h2><div class="media-strip">'+mediaFigure(FACTORY_MEDIA.finance,"Экономический контур MMW","Финансовая логика проекта перед расчётом показателей.")+'</div>'+mmwEconomicCalculator()+'</section><section><h2>Принципы работы</h2><div class="accordion"><details open><summary>От идеи к модели</summary><p>Каждый проект проходит через проблему, продукт, аудиторию, площадку, реализационную модель и экономику.</p></details><details><summary>Данные прежде обещаний</summary><p>Если бюджет, цена, срок или доходность не подтверждены исходными данными, они обозначаются как требующие расчёта.</p></details><details><summary>Проект прежде функции</summary><p>Роли MMW определяются конкретной сделкой и моделью проекта.</p></details></div><div class="media-strip">'+mediaFigure(FACTORY_MEDIA.energyAlt2,"Принципы MMW","Управленческий контур и рабочая среда проекта.")+'</div></section><section><h2>Статус портфеля</h2><p class="section-intro">Все шесть представленных направлений обозначены как концепты. Это рабочие проектные модели для дальнейшей проверки, а не заявления о запущенных объектах.</p><a class="button" href="#/projects">Открыть портфель</a></section></div>'}

